"""
DevPilot AI - Test Case ORM Model.
"""

import uuid
from typing import Optional, Dict, Any, List, TYPE_CHECKING
from sqlalchemy import String, Text, Integer, Boolean, ForeignKey, JSON
from sqlalchemy.orm import Mapped, mapped_column, relationship
from ..db.base import Base, TimestampMixin

if TYPE_CHECKING:
    from .project import Project
    from .spec import ApiEndpoint
    from .execution import TestResult


class TestCase(Base, TimestampMixin):
    """Structured declarative test case definition generated by LLM and validated by Pydantic."""

    __tablename__ = "test_cases"

    id: Mapped[str] = mapped_column(
        String(36),
        primary_key=True,
        default=lambda: str(uuid.uuid4()),
    )
    project_id: Mapped[str] = mapped_column(
        String(36),
        ForeignKey("projects.id", ondelete="CASCADE"),
        index=True,
        nullable=False,
    )
    endpoint_id: Mapped[str] = mapped_column(
        String(36),
        ForeignKey("api_endpoints.id", ondelete="CASCADE"),
        index=True,
        nullable=False,
    )
    test_id_code: Mapped[str] = mapped_column(String(64), index=True, nullable=False)
    name: Mapped[str] = mapped_column(String(255), nullable=False)
    description: Mapped[Optional[str]] = mapped_column(Text, nullable=True)
    category: Mapped[str] = mapped_column(
        String(50),
        nullable=False,
        index=True,
        comment="positive, negative, boundary, security, regression",
    )
    priority: Mapped[str] = mapped_column(String(20), default="medium")

    # Request payload components
    request_headers: Mapped[Dict[str, str]] = mapped_column(JSON, default=dict)
    path_params: Mapped[Dict[str, Any]] = mapped_column(JSON, default=dict)
    query_params: Mapped[Dict[str, Any]] = mapped_column(JSON, default=dict)
    request_body: Mapped[Dict[str, Any]] = mapped_column(JSON, default=dict)

    # Assertions
    expected_status: Mapped[int] = mapped_column(Integer, nullable=False)
    expected_response_checks: Mapped[Dict[str, Any]] = mapped_column(JSON, default=dict)

    # Provenance and audit metadata
    source_references: Mapped[List[str]] = mapped_column(JSON, default=list)
    generation_model: Mapped[str] = mapped_column(String(100), default="unknown")
    prompt_version: Mapped[str] = mapped_column(String(50), default="v1.0")
    requires_review: Mapped[bool] = mapped_column(Boolean, default=False)
    is_approved: Mapped[bool] = mapped_column(Boolean, default=True)
    is_active: Mapped[bool] = mapped_column(Boolean, default=True)

    # Relationships
    project: Mapped["Project"] = relationship("Project", back_populates="test_cases")
    endpoint: Mapped["ApiEndpoint"] = relationship("ApiEndpoint", back_populates="test_cases")
    test_results: Mapped[List["TestResult"]] = relationship(
        "TestResult",
        back_populates="test_case",
        cascade="all, delete-orphan",
    )
